export default function Dashboard(){

return(

<div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-purple-900 via-slate-900 to-indigo-900">

<div className="glass-card p-10 text-center shadow-glow">

<h1 className="text-4xl font-bold text-gradient mb-6">
Dashboard
</h1>

<button
className="px-6 py-3 rounded-lg bg-gradient-to-r from-purple-500 to-cyan-400 hover:scale-105 transition"
onClick={()=>{
localStorage.removeItem("userToken")
window.location.href="/"
}}
>
Logout
</button>

</div>

</div>

)

}
